    "chordProContent": "{c: Verse 1}\n  D       Bm      A      G         D\n1.สรรเสริญ สรรเสริญ สรรเสริญ ผู้เป็นเจ้าทรงเดชา\nA         Bm  A      E7            A7\nเวลาเช้า ควรข้าพเจ้า ร้องเพลง สรรเสริญพระนาม\nD       Bm      A       G        D\nสรรเสริญ สรรเสริญ สรรเสริญ แด่พระเจ้าผู้เมตตา\nBm D     G  D   G    A      D\nปรากฎ เป็นสามนั้น คือพระเจ้า เดียวกัน\n\n{c: Verse 2}\n  D       Bm      A       G         D\n2.สรรเสริญ สรรเสริญ สรรเสริญ ชาวสวรรค์ชาวโลกา\n A       Bm     A      E7        A7\nชวนกันมา ถวายพระเกียรติ แด่ผู้เป็นเจ้าองค์เดียว\nD   Bm A      G       D\nองค์ผู้บริสุทธิ์นั้น ควรมนุษย์จะบูชา\nBm  D    G  D   G   A   D\nผู้..ทรง สภาพอยู่ ตลอดกาลเวลา\n\n{c: Verse 3}\n  D       Bm      A      G           D\n3.สรรเสริญ สรรเสริญ สรรเสริญ แม้บางครั้งความมืดบัง\nA        Bm   A   E7      A7\nทำให้ตาคนบาปเรานี้ ไม่อาจเห็นรัศมี\nD    Bm    A     G         D\nแต่พระองค์ยังเป็นอยู่ ไม่มีใครเทียบเทียมได้\nBm D      G   D   G      A     D\nสมบูรณ์ ด้วยฤทธิ์เดช ความรัก ความเมตตา\n\n{c: Verse 3}\n  D       Bm      A      G         D\n4.สรรเสริญ สรรเสริญ สรรเสริญ ผู้เป็นเจ้าทรงฤทธา\nA       Bm    A    E7      A7\nราชกิจพระองค์สำแดง อำนาจในจักรวาล\nD       Bm      A      G         D\nสรรเสริญ สรรเสริญ สรรเสริญ ผู้ทรงรักชาวโลกา\nBm D     G  D   G    A      D\nปรากฏ เป็นสามนั้น คือพระเจ้า เดียวกัน\n",
