    "chordProContent": "{c: Verse 1}\n  Em     G      A                 B7\n1.ยาห์เวห์ ยาห์เวห์ ยาห์เวห์ องค์พระเจ้ายิ่งใหญ่\nEm     G      A                 B7\nยาห์เวห์ ยาห์เวห์ ยาห์เวห์ องค์พระเจ้ายิ่งใหญ่\n\n{c: Pre-Chorus}\n   Em\n** ยาห์เวห์ยิเรห์ พระเจ้าผู้จัดเตรียม\nC\nยาห์เวห์ราฟา พระเจ้าผู้รักษา\nAm                      B7\nยาห์เวห์ชาโลม พระเจ้าแห่งสันติสุข\nEm\nยาห์เวห์นิสสี พระเจ้าทรงมีชัย\nC\nอาโดนาย พระเจ้าจอมเจ้านาย\nAm                 B7\nเอลชัดดาย พระเจ้าผู้ทรงฤทธิ์\n\n{c: Chorus}\n    Em\n*** ถ้าเจ้าเชื่อ จะได้เห็นความยิ่งใหญ่\nC\nถ้าวางใจ จะได้เห็นการอัศจรรย์\nAm                        B7\nการช่วยเหลือ การช่วยกู้มาจากพระองค์\nEm\nถ้าเจ้าเชื่อ จะได้เห็นความยิ่งใหญ่\nC\nถ้าวางใจ จะได้เห็นการอัศจรรย์\nAm                        B7\nการช่วยเหลือ การช่วยกู้มาจากพระองค์\n\n{c: Bridge}\n      Em\n** เรานมัสการ แด่องค์จอมราชา\n     C\nเรายกย่องพระนาม ยาห์เวห์\n    Am\nเรานมัสการ แด่องค์จอมราชา\n     B7                   Em\nเรายกย่องพระนาม ยาห์เวห์ (ยาห์เวห์)",
