    "chordProContent": "{c: Verse 1}\n      C   G     Am   Em  \n1. ไม่มีรักใดๆ ที่ยิ่งใหญ่กว่านี้\n     F     C     Dm         G  \nที่พระองค์ยอมตาย บนไม้กางเขนเพื่อเรา\n      C    G      Am     Em  \nเมื่อเราเชื่อวางใจ พระเยซูทรงให้ชีวิต\n    F  C        Dm     G  C  \nคือชีวิตนิรันดร์ ที่บนสวรรค์บ้านของเรา\n\n{c: Chorus}\n           F     G     Em     Am  \n*** พระองค์เป็นทางนั้น ทางเดียวไปสู่ชีวิต\n        Dm G  \nเพราะพระเยซูคริสต์\n   Gm          C  \nแบกรับความผิดมากมาย\n       F      G      Em      Am  \nพระองค์เป็นความหวัง ให้ทุกคนที่กลับใจ  \n     Dm       G      C  \nเข้ามารับเอาชีวิตใหม่ในพระองค์\n\n{c: Outro}\n       Dm         G      C  \n* เข้ามารับความรักยิ่งใหญ่ในพระองค์",
