    "chordProContent": "{c: Verse 1}\n   G      C       G   C D\n1. ชีวิตข้าจะขอ มีเพียงพระองค์\nG          C        G D\nทรงประทานให้ข้า มีชีวิตใหม่\nEm                   C     G\nพระโลหิตชำระภายใน ความรักฟื้นฟูหัวใจ\nAm                  D\nสำหรับข้า พระองค์ทรงเป็นทุกสิ่ง\n\n{c: Verse 2}\n   G             C     G  C D\n2. พระองค์เป็นความหวัง ที่ข้าพึ่งพิง\n G            C          G D\nเพราะพระองค์ทรงช่วยเยียวยาทุกสิ่ง\nEm                C        G\nจิตวิญญาณข้าขอจำนน ต่อพระองค์เพียงผู้เดียว\nAm                D    D7\nพระเยซู ทรงเป็นทุกสิ่งของข้า\n\n{c: Chorus}\n             G          D         Em       D\n*** กางเขนคือชีวิต ทุกลมหายใจ ข้าเห็นชัยชนะของพระองค์\n         C          Bm\nผู้ทรงครอบครองทุกสิ่ง พระองค์\n             Am         D        G\nทรงกอปรกิจด้วยฤทธิ์  แสนอัศจรรย์ ชั่วชีวิตข้า\n\n",
