    "chordProContent": "{c: Verse 1}\n      G       G7     C  \n1.บนภูเขาซึ่งอยู่ไกล ได้แลเห็นไม้กางเขน\n   D7                    G  \nเป็นรอยแห่งความทุกข์ และความอาย\n    G      G7       C  \nแต่ใจข้ารักกางเขน ที่พระคริสต์ถูกตรึงตาย\n     D7              G  \nไถ่คนบาปให้รอดพ้น จากอบาย\n\n{c: Chorus}\n          D7            G                \n*** โดยเหตุนี้ ข้าจึงรักไม้กางเขน  \n       C            G  \nเพราะว่าเป็น ที่จะวางภาระลง\n   G              C             \nข้าก็คง ยึดกางเขนไว้ให้มั่น  \n      G        D7     G  \nแล้ววันหนึ่ง จะแลกเอามงกุฏงาม\n\n{c: Verse 2}\n        G      G7       C  \n2.ไม้กางเขนโบราณนั้น ชาวโลกพากันดูหมิ่น\n    D7            G  \nแต่ข้ารักกางเขนนั้นหนักหนา\n        G      G7     C  \nเพราะพระเยซูคริสต์เจ้า สละเนาในเมืองฟ้า\n    D7                G  \nเสด็จมา เพื่อยอมตายบนกางเขน\n\n{c: Verse 3}\n       G      G7      C  \n3.ที่กางเขนโบราณนั้น ข้าได้เห็นรัศมี\n     D7              G  \nพระโลหิตพระองค์ ได้หลั่งไหล\n      G    G7      C  \nเพื่อจะได้ชำระบาป ในตัวข้าให้สะอาด\n       D7              G  \nนั่นแหล่ะคือ ไม้กางเขนโบราณนั้น\n\n{c: Verse 4}\n       G       G7    C  \n4.ไม้กางเขนโบราณนั้น ยึดมันไว้จนวันตาย\n    D7             G  \nหากใครติเตียนข้า ไม่ละอาย\n      G    G7        C  \nเมื่อวันหนึ่งถึงเวลา พระองค์มารับข้าไป\n   D7             G  \nสู่สวรรค์ อยูที่นั้นสำราญใจ\n\n",
