    "chordProContent": "{c: Verse 1}\n      E        B           F#m         E\n1.ข้าได้ยินพระเยซูเรียกข้า โดยความรักพระองค์ทรงเรียกข้า\n       E          A            E     A     B    E\nโดยพระธรรมโอวาททรงเรียกข้า แบกกางเขนและตามเรา ตามเรามา\n\n{c: Verse 2}\n       E         B          F#m       E\n2.แม้ว่าทางมืดมัวทรงนำหน้า เมื่อจิตใจโศกเศร้า มีน้ำตา\n      E         A        E     A    B     E\nแต่วิญญาณชุ่มชื่นทุกเวลา ข้าจะตามไป ตามไป ทั่วทุกทาง  \n\n{c: Chorus}\n         E            B       \n*** ข้าจะแบกกางเขน แล้วเดินตาม \n     G#          C#m\nข้าจะแบกกางเขน แล้วเดินตาม  \n    Bm            A\nข้าจะแบกกางเขน แล้วเดินตาม \n      E     A     B    E  D\nแล้วจะตามไป ตามไป ทั่วทุกทาง   \n\n{c: Verse 3}\n        G         D           Am         G \n3. ขอพระองค์เสด็จนำหน้าข้า โปรดประทานสว่างฤทธิ์เดชมา\n    G             C        G     C     D    G\nแม้ใจข้าอ่อนเพลียโปรดรักษา ข้าจะตามไป ตามไป ทั่วทุกทาง\n{c: Verse 4}\n       G          D            Am       G\n4.แม้ว่าทางคดเคี้ยวทรงนำหน้า โปรดประทานอาหารสวรรค์มา\n    G          C           G     C     D    G\nเมื่อชีวิตวางวายทรงนำพา เพราะข้าตามไป ตามไป ทั่วทุกทาง\n\n{c: Chorus}\n         G            D       \n*** ข้าจะแบกกางเขน แล้วเดินตาม \n     B           Em\nข้าจะแบกกางเขน แล้วเดินตาม  \n    Dm            C\nข้าจะแบกกางเขน แล้วเดินตาม \n      G     C     D    G\nแล้วจะตามไป ตามไป ทั่วทุกทาง",
