    "chordProContent": "{c: Verse 1}\n  E                 C#m\n1.ฉันเห็นราชาแห่งพระสิริ มาด้วยเมฆและไฟบนฟ้า \n      F#m         B\nทั่วทั้งโลกา สะท้านสะเทือน \nE                   C#m\nฉันเห็นความรักและเมตตา ที่ได้ทรงชำระบาปเรา \n        F#m           B\nและทุกคนต่าง แซ่ซ้องสรรเสริญ \n\n{c: Chorus}\n      E/G# A     B   C#m  \n*** โฮซัน..นา  โฮซัน..นา \n   A       C#m  B\nโฮซันนา แด่ผู้สูง..สุด \n  E/G# A     B   C#m\nโฮซัน..นา  โฮซัน..นา \n   A       B  E\nโฮซันนา แด่ผู้สูงสุด \n\n{c: Verse 2}\n  E                  C#m\n2.ฉันเห็นบรรดาชนมากมาย ลุกขึ้นเพื่อทำตามพระทัย \n           F#m        B\nเปี่ยมด้วยความเชื่อ สุดสิ้นหัวใจ \nE                  C#m\nฉันเห็นเปลวไฟการฟื้นฟู เคลื่อนเข้ามาเมื่อเราร้องทูล \n       F#m        B\nและทุกหัวเข่า ร่ำร้องวิงวอน \n\n{c: Bridge}\n   A              B\n** ขอพระองค์ชำระหัวใจ \nE               C#m\nให้ดวงตาฉันเห็น สิ่งที่ยังซ่อนอยู่ \nA             B         C#m\nขอให้ฉันได้มีความรัก เหมือนพระองค์ \nA               B\nขอพระองค์ละลายหัวใจ \nE              C#m\nมอบชีวิตถวาย อยู่ในน้ำพระทัย \nA             B      A\nทุกวันคืนที่ฉันเดินไป สู่นิจนิรันดร์ \n",
