    "chordProContent": "{c: Verse 1}\n         D/F#       G           A         D\n1: ในความมืดมน เรานั้นเฝ้ารอ  ไร้ความหวัง หมดหนทาง \n    D/F#        G           A          D\nจากสวรรค์พระองค์นั้นลงมา  ทรงมองข้าด้วยพระเมตตา \n      D/F#      G            A         D\nเพื่อให้เป็นไปตามน้ำพระทัย  พระองค์ให้พระบุตรลงมา \n     D/F#          G        A         D\nจากบัลลังก์เปี่ยมด้วยพระสิริ  ทรงบังเกิดอยู่ในรางหญ้า \n\n{c: Chorus}\n     D            G2                           \n*** สรรเสริญพระเจ้า พระบิดา  \n Bm7          D/A   A\nสรรเสริญพระบุตร พระวิญญาณ \nD            G2           \nโอ้ พระเจ้าแห่ง พระสิริ  \nBm7    G2         A   D\nสรรเสริญนิรันดร์แด่องค์จอมราชา \n\n{c: Verse 2}\n        D/F#     G            A        D\n2: เพื่อคืนดีให้ผู้หลงหายไป  และเพื่อให้แผ่นดินลงมา \n      D/F#    G           A          D\nเพื่อทุกสิ่งจะได้รับการไถ่  ทรงรับไว้กางเขนหนักหนา \n       D/F#   G          A        D\nพระองค์ทรงเห็นที่สิ้นสุด  แม้ในความทุกข์ทรมาน \n     D/F#   G            A         D\nทรงรับรู้นี่คือหนทางเดียว  พระเยซูจึงทรงยอมตาย \n\n{c: Verse 3}\n        Bm        G       A            D\n3: และในเช้าที่พระองค์ฟื้น  ทั้งสวรรค์ต้องหยุดหายใจ \n      Bm        G              A         D\nและก้อนหินต้องถูกเคลื่อนไป  เพราะลูกแกะชนะความตาย \n   Bm       G        A           D\nผู้ที่ตายไปกลับฟื้นมา  ทูตสวรรค์ยืนขึ้นสรรเสริญ \n     Bm     G         A          D\nแด่วิญญาณผู้ที่เคยมา  พระบิดาเยียวยากลับคืน \n\n{c: Verse 4}\n       D/F#       G            A          D\n4: คริสตจักรพระคริสต์เริ่มเกิด  พระวิญญาณได้จุดดวงไฟ \n       D/F#   G          A       D\nและความจริงชีวิตพระองค์  ไม่ล้มลง ไม่สิ้นไป \n     D/F#    G          A        D\nด้วยโลหิตและในพระนาม  ในเสรีนั้นข้าเป็นไท \n         D/F#   G       A       D\nเพราะความรักในพระเยซู  ผู้ฟื้นคืนชีวิตข้าใหม่ \n\n{c: Outro}\n   D/F#  G2         A   D\n* สรรเสริญนิรันดร์แด่องค์จอมราชา \n",
